function normalizeTryout(v={}){
 const ratings={};for(const [k] of allTryoutSkills){const r=v.ratings?.[k];if(r!==undefined&&r!==null&&r!==''&&(!Number.isInteger(r)||r<1||r>5))throw Error('Tryout ratings must be whole numbers from 1–5 or not observed.');ratings[k]=r===''||r==null?null:r;}
 return {number:clean(v.number,20),date:/^\d{4}-\d{2}-\d{2}$/.test(v.date||'')?v.date:'',evaluator:clean(v.evaluator,80),positions:[...new Set((Array.isArray(v.positions)?v.positions:[]).filter(n=>roleBy(n)).map(String))],selection:Object.hasOwn(selectionLabels,v.selection)?v.selection:'unassigned',captain:Object.hasOwn(captainLabels,v.captain)?v.captain:'unassessed',starterNotes:clean(v.starterNotes),backupNotes:clean(v.backupNotes),captainNotes:clean(v.captainNotes),evidence:clean(v.evidence),nextStep:clean(v.nextStep,2000),ratings,updated:clean(v.updated,40)};
}
function normalizeTryoutDraft(d){return {playerId:clean(d.playerId,100),name:clean(d.name,80),grade:clean(d.grade,20),role:roleBy(d.role)?d.role:'',secondary:roleBy(d.secondary)?d.secondary:'',...normalizeTryout(d)};}
function tryoutSummary(t){const r=tryoutSkills.map(([k])=>t?.ratings?.[k]).filter(Number.isFinite);return {count:r.length,average:r.length?(r.reduce((a,b)=>a+b,0)/r.length).toFixed(1):null};}
