function setTryoutField(name,value){const d=state.tryoutDrafts?.[activeTryout];if(!d)return;if(name.startsWith('skill_')){const key=name.slice(6);if(!allTryoutSkills.some(([k])=>k===key))return;const n=value===''?null:Number(value);if(n!==null&&(!Number.isInteger(n)||n<1||n>5))return;d.ratings[key]=n;}else if(name.startsWith('pos_')){const key=name.slice(4);if(!roleBy(key))return;d.positions=d.positions.filter(n=>n!==key);if(value)d.positions.push(key);}else if(['name','grade','role','secondary','number','date','evaluator','selection','captain','starterNotes','backupNotes','captainNotes','evidence','nextStep'].includes(name))d[name]=value;persist();const summary=tryoutSummary(d);if($('tryout-progress'))$('tryout-progress').textContent=`${summary.count}/12 core skills observed${summary.average?' · '+summary.average+' / 5':''}`;if($('tryout-save-status'))$('tryout-save-status').textContent=storageIssue?'Not saved — export a backup':'Draft saved on this device';}
function saveTryout(key=activeTryout){const d=state.tryoutDrafts?.[key];if(!d||!clean(d.name,80))throw Error('Enter the player’s name before saving.');const t=normalizeTryout({...d,updated:new Date().toISOString()});let p=state.players.find(p=>p.id===d.playerId);if(!p){if(state.players.length>=200)throw Error('This roster supports up to 200 players.');p={id:uid(),ratings:[null,null,null,null,null],notes:'',goals:[]};state.players.push(p);}Object.assign(p,{name:clean(d.name,80),grade:clean(d.grade,20),role:roleBy(d.role)?d.role:'',secondary:roleBy(d.secondary)?d.secondary:'',tryout:t});delete state.tryoutDrafts[key];activeTryout=null;persist();return p;}
function skillRows(skills,d){return skills.map(([key,title,cue])=>`<fieldset class="tryout-skill"><legend>${title}<small>${cue}</small></legend><div class="tap-scale">${[['','N/O'],...[1,2,3,4,5].map(n=>[n,n])].map(([value,label])=>`<label><input data-tryout name="skill_${key}" type="radio" value="${value}" ${d.ratings[key]===(value===''?null:value)?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset>`).join('');}
function tryoutOptions(labels,current){return Object.entries(labels).map(([k,v])=>`<option value="${k}" ${k===current?'selected':''}>${v}</option>`).join('');}
function renderTryout(){const d=state.tryoutDrafts?.[activeTryout];if(!d){activeTryout=null;return renderPlayers();}const sum=tryoutSummary(d);return heading('Tryout evaluation','Observe the action. Tap a score. Record the evidence.',btn(icon('left')+'Roster','tryout-back','','secondary')+btn(icon('print')+'Print form','print-tryout','','secondary'))+`<form id="tryout-form" class="tryout-form"><div class="storage-banner"><strong>Field-ready on iPad.</strong> Every change saves a draft in this browser. Save the evaluation to add it to your roster. Export a backup before moving devices.</div><section class="panel"><div class="eyebrow">01 · PLAYER & SESSION</div><h2>Who are you evaluating?</h2><div class="field-grid"><label>Player name *<input data-tryout name="name" required maxlength="80" autocomplete="off" value="${esc(d.name)}"></label><label>Tryout / pinnie number<input data-tryout name="number" maxlength="20" value="${esc(d.number)}" inputmode="numeric"></label><label>Grade<select data-tryout name="grade"><option value="">Not specified</option>${[6,7,8,9,10,11,12].map(n=>`<option ${String(n)===d.grade?'selected':''}>${n}</option>`).join('')}</select></label><label>Evaluation date<input data-tryout name="date" type="date" value="${esc(d.date)}"></label><label>Evaluator<input data-tryout name="evaluator" maxlength="80" value="${esc(d.evaluator)}"></label></div></section><section class="panel"><div class="eyebrow">02 · SKILL SET</div><h2>Rate what you see</h2><div class="scale-key">${[['1','Needs support'],['2','Developing'],['3','Meets team standard'],['4','Strong & consistent'],['5','Exceptional at this level']].map(([n,t])=>`<span><b>${n}</b>${t}</span>`).join('')}</div><p class="footnote">Judge age-appropriate, live play under comparable pressure. N/O = not observed; it is never scored as zero. A 5 needs repeated evidence. The core average is a discussion aid, not an automatic selection.</p>${skillRows(tryoutSkills,d)}<details class="tryout-details" ${d.positions.includes('1')||d.role==='1'||keeperSkills.some(([k])=>d.ratings[k]!==null)?'open':''}><summary>Goalkeeper skills · optional</summary>${skillRows(keeperSkills,d)}</details></section><section class="panel"><div class="eyebrow">03 · ROLE & DEPTH</div><h2>Potential position assignments</h2><p class="footnote">Select every role worth testing in the 4-2-3-1, then name the best current fit.</p><div class="position-picks">${C.roles.map(r=>`<label><input data-tryout name="pos_${r.number}" type="checkbox" ${d.positions.includes(r.number)?'checked':''}><span><b>${r.number}</b>${esc(r.name)}</span></label>`).join('')}</div><div class="field-grid"><label>Primary position<select data-tryout name="role">${roleOptions(d.role)}</select></label><label>Secondary position<select data-tryout name="secondary">${roleOptions(d.secondary)}</select></label><label>Projected squad role<select data-tryout name="selection">${tryoutOptions(selectionLabels,d.selection)}</select></label></div><div class="field-grid"><label>Starter notes<textarea data-tryout name="starterNotes" maxlength="5000" placeholder="Starting role, strengths under pressure, and evidence to confirm.">${esc(d.starterNotes)}</textarea></label><label>Backup / rotation notes<textarea data-tryout name="backupNotes" maxlength="5000" placeholder="Who can this player cover? Match situations, readiness and next development need.">${esc(d.backupNotes)}</textarea></label></div></section><section class="panel"><div class="eyebrow">04 · LEADERSHIP</div><h2>Potential captain candidates</h2><label>Captain assessment<select data-tryout name="captain">${tryoutOptions(captainLabels,d.captain)}</select></label><p class="footnote">Look for consistent behavior across sessions. Leadership can be quiet; assess support and responsibility as well as voice.</p><details class="tryout-details" ${['candidate','consider'].includes(d.captain)||leadershipSkills.some(([k])=>d.ratings[k]!==null)?'open':''}><summary>Leadership ratings · optional</summary>${skillRows(leadershipSkills,d)}</details><label>Captain evidence & follow-up<textarea data-tryout name="captainNotes" maxlength="5000" placeholder="How did the player organize, include others, handle mistakes or model standards? Who will observe again?">${esc(d.captainNotes)}</textarea></label></section><section class="panel"><div class="eyebrow">05 · EVIDENCE & PROGRESSION</div><h2>Make the next session useful</h2><label>Specific observations<textarea data-tryout name="evidence" maxlength="5000" placeholder="Activity / pressure → action → outcome. Include the context for the rating.">${esc(d.evidence)}</textarea></label><label>Next coaching cue & retest<textarea data-tryout name="nextStep" maxlength="2000" placeholder="One cue, a practice activity, and what to look for at the next tryout.">${esc(d.nextStep)}</textarea></label></section><div class="tryout-footer"><div><strong id="tryout-progress">${sum.count}/12 core skills observed${sum.average?' · '+sum.average+' / 5':''}</strong><small id="tryout-save-status" role="status">${storageIssue?'Draft could not be saved':'Draft saved on this device'}</small></div><div class="head-actions">${btn('Keep draft & return','tryout-back','','secondary')}<button class="btn" type="submit">${icon('save')}Save evaluation</button></div></div><p id="form-error" role="alert" class="tryout-error"></p></form>`;}
function renderTryoutRoster(){const players=state.players.filter(p=>tryoutFilter==='all'||(tryoutFilter==='captains'?['candidate','consider'].includes(p.tryout?.captain):p.tryout?.selection===tryoutFilter));return `<section class="panel tryout-roster"><div class="panel-head"><div><div class="eyebrow">TRYOUT WORKSPACE</div><h2>Evaluate. Compare. Build the squad.</h2></div>${btn(icon('plus')+(state.tryoutDrafts?.new?'Resume new player draft':'New tryout evaluation'),'start-tryout')}</div><div class="head-actions">${btn(icon('book')+'Tryout stations & warm-up','guide-page','data-page="1"','secondary')}${btn(icon('print')+'Print blank form','print-blank-tryout','','secondary')}${btn(icon('download')+'Export backup','export-backup','','secondary')}</div><div class="tryout-filters" role="group" aria-label="Filter tryout roster">${[['all','All players'],['starter','Starters'],['backup','Backups'],['rotation','Rotation'],['develop','Development'],['captains','Captain watchlist']].map(([k,t])=>`<button class="btn ${tryoutFilter===k?'':'secondary'}" data-action="tryout-filter" data-filter="${k}" aria-pressed="${tryoutFilter===k}">${t}</button>`).join('')}</div>${players.length?`<div class="tryout-cards">${players.map(p=>{const t=p.tryout,s=tryoutSummary(t);return `<article class="tryout-card"><div class="panel-head"><div><small>${t?.number?'#'+esc(t.number)+' · ':''}${t?.date?esc(t.date):'Awaiting tryout evaluation'}</small><h3>${esc(p.name)}</h3></div><span class="tag">${s.average??'N/O'}${s.average?' / 5':''}</span></div><p>${esc(roleBy(p.role)?.name||'Position to assess')}${p.secondary?' · '+esc(roleBy(p.secondary)?.name||''):''}</p><div class="head-actions"><span class="tag">${selectionLabels[t?.selection]||'Not assigned'}</span>${['candidate','consider'].includes(t?.captain)?`<span class="tag captain-tag">${captainLabels[t.captain]}</span>`:''}</div><p class="footnote">${s.count}/12 skills observed${t?.positions?.length?' · Test roles: '+t.positions.join(', '):''}</p>${t?.starterNotes?`<p><strong>Starter:</strong> ${esc(t.starterNotes)}</p>`:''}${t?.backupNotes?`<p><strong>Backup:</strong> ${esc(t.backupNotes)}</p>`:''}${t?.captainNotes?`<p><strong>Leadership:</strong> ${esc(t.captainNotes)}</p>`:''}<div class="head-actions">${btn(state.tryoutDrafts?.[p.id]?'Resume draft':'Evaluate','start-tryout',`data-id="${esc(p.id)}"`)}${btn('Profile','player-profile',`data-id="${esc(p.id)}"`,'secondary')}</div></article>`;}).join('')}</div>`:empty('No players in this view','Add an evaluation or choose a different roster filter.')}<p class="footnote">Tryout skill averages use the 12 core skills observed so far. Existing five-category scores remain separate in player profiles. Save each updated evaluation to replace that player’s current assessment.</p></section>`;}
function tryoutPrint(t={},p={}){const ratings=t.ratings||{};return `<p>Player: <strong>${esc(p.name||'________________________________')}</strong> &nbsp; Number: ${esc(t.number||'________')} &nbsp; Grade: ${esc(p.grade||'____')}</p><p>Date: ${esc(t.date||'____________')} &nbsp; Evaluator: ${esc(t.evaluator||'________________________')}</p><p>1 Needs support · 2 Developing · 3 Meets team standard · 4 Strong & consistent · 5 Exceptional at this level · N/O Not observed</p><table><thead><tr><th>Skill / observable action</th><th>Rating</th></tr></thead><tbody>${[...tryoutSkills,...keeperSkills,...leadershipSkills].map(([k,title,cue])=>`<tr><td><strong>${title}</strong> — ${cue}</td><td style="white-space:nowrap">${ratings[k]||'1　2　3　4　5　N/O'}</td></tr>`).join('')}</tbody></table><p>Potential positions: ${esc(t.positions?.map(n=>n+' '+roleBy(n)?.name).join('; ')||'1 GK · 2 RB · 4 RCB · 5 LCB · 3 LB · 6 DM · 8 CM · 7 RW · 10 AM · 11 LW · 9 ST')}</p><p>Primary: ${esc(roleBy(p.role)?.name||'____________')} &nbsp; Secondary: ${esc(roleBy(p.secondary)?.name||'____________')}</p>${[['Squad role',selectionLabels[t.selection]],['Starter notes',t.starterNotes],['Backup / rotation notes',t.backupNotes],['Captain assessment',captainLabels[t.captain]],['Captain evidence',t.captainNotes],['Observations',t.evidence],['Next coaching cue & retest',t.nextStep]].map(([label,v])=>`<p style="white-space:pre-wrap"><strong>${label}:</strong> ${esc(v||'________________________________________________________________________')}</p>`).join('')}`;}

