let state,storageIssue=false;
function normalizeBackup(input){
 if(!input||input.version!==1||!Array.isArray(input.players)||!Array.isArray(input.plans)||!Array.isArray(input.boards))throw Error('Choose a Posición version 1 coaching backup.');
 if(input.players.length>200||input.plans.length>300||input.boards.length>200)throw Error('This backup contains more records than supported.');
 const out=defaults();
 out.settings={coach:clean(input.settings?.coach||out.settings.coach,80),team:clean(input.settings?.team||out.settings.team,80),week:clamp(parseInt(input.settings?.week)||1,1,14)};
 out.players=input.players.map(p=>{
  if(!p.id||!clean(p.name,80)||!Array.isArray(p.ratings)||p.ratings.length!==5||p.ratings.some(r=>r!==null&&(!Number.isFinite(r)||r<1||r>5)))throw Error('A player record has invalid ratings.');
  return {id:clean(p.id,100),name:clean(p.name,80),grade:clean(p.grade,20),role:clean(p.role,2),secondary:clean(p.secondary,2),notes:clean(p.notes),ratings:p.ratings,tryout:p.tryout?normalizeTryout(p.tryout):null,goals:(p.goals||[]).slice(0,100).map(g=>{
   if(![g.baseline,g.current,g.target].every(Number.isFinite)||g.baseline<0||g.current<0||g.target<0||g.target===g.baseline)throw Error('A development goal has invalid measurements.');
   return {id:clean(g.id,100)||uid(),title:clean(g.title,180),baseline:g.baseline,current:g.current,target:g.target,review:clean(g.review,20),stage:clamp(Number(g.stage)||1,1,4),practice:clean(g.practice,100)};
  })};
 });
 out.tryoutDrafts=Object.fromEntries(Object.entries(input.tryoutDrafts||{}).slice(0,201).filter(([key])=>key==='new'||out.players.some(p=>p.id===key)).map(([key,d])=>[key,normalizeTryoutDraft(d)]));
 const normalizePlan=p=>{
  if(!p.id||!Array.isArray(p.blocks)||p.blocks.length>60)throw Error('A practice plan is not valid.');
  return {id:clean(p.id,100),name:clean(p.name,120)||'Practice plan',target:clamp(Number(p.target)||90,15,240),notes:clean(p.notes),created:clean(p.created,40),blocks:p.blocks.map(b=>{
   if(!Number.isFinite(Number(b.minutes))||Number(b.minutes)<1||Number(b.minutes)>180)throw Error('Practice block durations must be 1–180 minutes.');
   return {id:clean(b.id,100)||uid(),title:clean(b.title,180)||'Practice block',minutes:Number(b.minutes),note:clean(b.note,1000),drillId:drillBy(b.drillId)?b.drillId:null};
  })};
 };
 out.plans=input.plans.map(normalizePlan);out.activePlan=out.plans.some(p=>p.id===input.activePlan)?input.activePlan:out.plans[0]?.id||null;
 const normBoard=b=>{
  if(!shapes[b?.phase]||!b.positions)throw Error('A tactics board is not valid.');
  const point=p=>{if(!Array.isArray(p)||p.length!==2||!p.every(Number.isFinite))throw Error('A tactics position is not valid.');return [clamp(p[0],2,98),clamp(p[1],4,96)];};
  const positions={};for(const r of C.roles)positions[r.number]=point(b.positions[r.number]||shapes[b.phase].positions[r.number]);
  return {phase:b.phase,name:clean(b.name,100)||shapes[b.phase].title,positions,arrows:(b.arrows||[]).slice(0,100).map(a=>({a:point(a.a),b:point(a.b),type:a.type==='run'?'run':'pass'})),ball:point(b.ball||[43,53]),opponents:!!b.opponents};
 };
 out.board=input.board?normBoard(input.board):out.board;out.boards=input.boards.map(b=>({id:clean(b.id,100)||uid(),...normBoard(b)}));
 out.favorites=(input.favorites||[]).filter(id=>[...C.drills,...C.techniques,...C.sessions].some(d=>d.id===id));
 out.completedWeeks=(input.completedWeeks||[]).filter(n=>Number.isInteger(n)&&n>=1&&n<=14);
 out.weekNotes=Object.fromEntries(Object.entries(input.weekNotes||{}).filter(([k])=>Number(k)>=1&&Number(k)<=14).map(([k,v])=>[k,clean(v)]));
 const normMatch=m=>{
  const fm=freshMatch();fm.id=clean(m?.id,100)||fm.id;for(const k of ['opponent','date','route','trigger','threat','adjustment','halftime','reflection'])fm[k]=clean(m?.[k]??fm[k],k==='date'?20:2000);
  fm.ownGoals=clamp(Number(m?.ownGoals)||0,0,99);fm.awayGoals=clamp(Number(m?.awayGoals)||0,0,99);
  for(const k of Object.keys(fm.metrics))fm.metrics[k]=clamp(Number(m?.metrics?.[k])||0,0,999);
  fm.scenario=['level','leading','trailing','ten'].includes(m?.scenario)?m.scenario:'level';return fm;
 };
 out.match=normMatch(input.match);out.history=(input.history||[]).slice(0,300).map(m=>({id:clean(m.id,100)||uid(),...normMatch(m)}));
 out.cifChecks=(input.cifChecks||[]).filter(v=>Number.isInteger(v)&&v>=0&&v<13);
 out.assignments=Object.fromEntries(Object.entries(input.assignments||{}).slice(0,20).map(([k,v])=>[clean(k,50),{first:clean(v?.first,100),backup:clean(v?.backup,100)}]));
 return out;
}
try{const raw=localStorage.getItem(KEY);state=raw?normalizeBackup(JSON.parse(raw)):defaults();}catch(e){state=defaults();storageIssue=true;}
